function Shop() {
  const [location, setLocation] = useLocation();
  const params = readUrlParams();
  const initialQ = params.get('q') || ''; const initialCategory = params.get('category') || 'All';
  const [query, setQuery] = useState(initialQ); const [category, setCategory] = useState(initialCategory); const [maxPrice, setMaxPrice] = useState(Number(params.get('max') || 4000)); const [sort, setSort] = useState(params.get('sort') || 'featured'); const [filterOpen, setFilterOpen] = useState(false);
  useEffect(() => { const p = new URLSearchParams(); if (query) p.set('q', query); if (category !== 'All') p.set('category', category); if (maxPrice !== 4000) p.set('max', String(maxPrice)); if (sort !== 'featured') p.set('sort', sort); const next = p.toString(); const current = location.split('?')[1] || ''; if (next !== current) setLocation(`/shop${next ? `?${next}` : ''}`, { replace: true }); }, [query, category, maxPrice, sort]);
  const shown = useMemo(() => {
    const q = query.trim().toLowerCase();
    const list = products.filter(p => (!q || [p.name, p.category, p.material, p.color, ...p.tags].join(' ').toLowerCase().includes(q)) && (category === 'All' || p.category === category) && p.price <= maxPrice);
    return [...list].sort((a, b) => sort === 'low' ? a.price - b.price : sort === 'high' ? b.price - a.price : a.id.localeCompare(b.id));
  }, [query, category, maxPrice, sort]);
  const clear = () => { setQuery(''); setCategory('All'); setMaxPrice(4000); setSort('featured'); };
  return <><Meta title="Shop the collection" description="Explore considered sofas, dining tables, storage, bedroom, and kitchen pieces from FurniVision." /><main className="mx-auto max-w-[1440px] px-5 py-10 md:px-8 md:py-16"><div className="flex flex-wrap items-end justify-between gap-6 border-b border-[hsl(var(--border))] pb-9"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]">The collection / {products.length} pieces</p><h1 className="mt-4 font-display text-6xl leading-[.9] tracking-[-.05em] md:text-8xl">Shop <em>well.</em></h1></div><div className="w-full max-w-md md:w-auto"><div className="flex items-center gap-3 border-b border-[hsl(var(--foreground)/.35)] pb-3"><Search size={18} className="text-[hsl(var(--muted-foreground))]" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search by room, material, or piece" aria-label="Search products by room material or piece" className="w-full bg-transparent text-sm outline-none placeholder:text-[hsl(var(--muted-foreground))]" data-testid="input-catalog-search" />{query && <button onClick={() => setQuery('')} aria-label="Clear search" data-testid="button-clear-search"><X size={16} /></button>}</div><p className="mt-2 font-mono-ui text-[9px] uppercase tracking-[.12em] text-[hsl(var(--muted-foreground))]">Try “walnut”, “soft”, or “storage”</p></div></div>
      <div className="flex items-center justify-between border-b border-[hsl(var(--border))] py-4"><button onClick={() => setFilterOpen(!filterOpen)} className="flex items-center gap-2 text-sm font-semibold md:hidden" data-testid="button-mobile-filters"><SlidersHorizontal size={16} /> Filters</button><div className="hidden items-center gap-2 md:flex"><span className="mr-2 font-mono-ui text-[10px] uppercase tracking-[.18em] text-[hsl(var(--muted-foreground))]">Filter by</span>{['All', 'Living', 'Dining', 'Bedroom', 'Storage', 'Kitchen'].map(c => <button key={c} onClick={() => setCategory(c)} className={`px-3 py-2 text-xs ${category === c ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'hover:bg-[hsl(var(--muted))]'}`} data-testid={`button-filter-${c.toLowerCase()}`}>{c}</button>)}</div><label className="flex items-center gap-2 text-xs"><span className="hidden text-[hsl(var(--muted-foreground))] sm:inline">Sort</span><select value={sort} onChange={e => setSort(e.target.value)} aria-label="Sort products" className="bg-transparent font-semibold outline-none" data-testid="select-sort"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select><ChevronDown size={14} /></label></div>
      {filterOpen && <div className="grid gap-5 border-b border-[hsl(var(--border))] py-5 md:hidden animate-fade"><div className="flex flex-wrap gap-2">{['All', 'Living', 'Dining', 'Bedroom', 'Storage', 'Kitchen'].map(c => <button key={c} onClick={() => setCategory(c)} className={`px-3 py-2 text-xs ${category === c ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'bg-[hsl(var(--muted))]'}`} data-testid={`button-mobile-filter-${c.toLowerCase()}`}>{c}</button>)}</div><label className="text-xs">Max price <input type="range" min="100" max="4000" step="10" value={maxPrice} onChange={e => setMaxPrice(Number(e.target.value))} className="mx-3 align-middle accent-[hsl(var(--accent))]" data-testid="input-price-range" /><span className="font-mono-ui">{money(maxPrice)}</span></label></div>}
      <div className="mb-7 mt-8 flex items-center justify-between"><p className="font-mono-ui text-[10px] uppercase tracking-[.15em] text-[hsl(var(--muted-foreground))]" data-testid="text-result-count">{shown.length} {shown.length === 1 ? 'piece' : 'pieces'}</p>{(query || category !== 'All' || maxPrice !== 4000) && <button onClick={clear} className="text-xs underline underline-offset-4" data-testid="button-clear-filters">Clear all</button>}</div>
      {shown.length ? <div className="grid grid-cols-2 gap-x-4 gap-y-12 md:grid-cols-3 md:gap-x-6 lg:grid-cols-4">{shown.map((p, i) => <ProductCard key={p.id} product={p} index={i} />)}</div> : <div className="grid min-h-[360px] place-items-center border border-dashed border-[hsl(var(--border))] bg-[hsl(var(--muted)/.5)] px-6 text-center"><div><Sparkles className="mx-auto mb-4 text-[hsl(var(--accent))]" size={25} /><h2 className="font-display text-3xl">Nothing in that room.</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Try another material, category, or a wider price range.</p><button onClick={clear} className="mt-6 border-b border-[hsl(var(--foreground))] pb-1 text-sm font-semibold" data-testid="button-empty-reset">Reset filters</button></div></div>}</main><Footer /></>;
}

function ProductDetail() {
  const { slug } = useParams<{ slug: string }>(); const product = products.find(p => p.slug === slug); const { wishlist, toggleWish, addCart } = useStore(); const [added, setAdded] = useState(false);
  if (!product) return <NotFound />;
  const saved = wishlist.includes(product.id);
  const add = () => { addCart(product.id); setAdded(true); window.setTimeout(() => setAdded(false), 1800); };
  return <><Meta title={product.name} description={product.description} /><main className="mx-auto max-w-[1440px] px-5 py-6 md:px-8 md:py-10"><Link href="/shop" className="mb-7 inline-flex items-center gap-2 text-xs font-semibold" data-testid="link-back-shop"><ArrowLeft size={15} /> Back to collection</Link><div className="grid gap-10 md:grid-cols-[1.1fr_.9fr] md:gap-16"><div className="bg-[hsl(var(--secondary))]"><img src={product.image} alt={product.name} className="aspect-square h-auto w-full object-cover md:aspect-[1.06]" /></div><div className="flex flex-col justify-center md:py-10"><p className="font-mono-ui text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]">{product.category} / {product.material}</p><h1 className="mt-5 max-w-xl font-display text-6xl leading-[.9] tracking-[-.05em] md:text-8xl">{product.name}</h1><p className="mt-6 text-lg leading-7 text-[hsl(var(--muted-foreground))]">{product.description}</p><div className="mt-7 flex items-center justify-between border-y border-[hsl(var(--border))] py-5"><span className="text-xl">{money(product.price)}</span><span className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-[hsl(var(--muted-foreground))]">Made for the long haul</span></div><div className="mt-6 flex gap-3"><button onClick={add} className="flex flex-1 items-center justify-center gap-3 bg-[hsl(var(--primary))] px-5 py-4 text-sm font-semibold text-[hsl(var(--primary-foreground))] transition hover:bg-[hsl(var(--accent))]" data-testid={`button-detail-add-${product.id}`}>{added ? <><Check size={17} /> Added to cart</> : <>Add to cart <ArrowRight size={16} /></>}</button><button onClick={() => toggleWish(product.id)} aria-label={saved ? 'Remove from wishlist' : 'Save to wishlist'} className={`grid w-14 place-items-center border border-[hsl(var(--border))] transition hover:border-[hsl(var(--accent))] ${saved ? 'text-[hsl(var(--accent))]' : ''}`} data-testid={`button-detail-wish-${product.id}`}><Heart size={20} fill={saved ? 'currentColor' : 'none'} /></button></div><div className="mt-9 grid gap-4 border-t border-[hsl(var(--border))] pt-7">{product.details.map((d, i) => <div key={d} className="flex gap-4 text-sm"><span className="font-mono-ui text-[10px] text-[hsl(var(--accent))]">0{i + 1}</span><span>{d}</span></div>)}</div></div></div><section className="mt-20 border-t border-[hsl(var(--border))] pt-8"><p className="font-mono-ui text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]">You may also like</p><div className="mt-7 grid grid-cols-2 gap-4 md:grid-cols-4 md:gap-6">{products.filter(p => p.id !== product.id).slice(0, 4).map((p, i) => <ProductCard key={p.id} product={p} index={i} />)}</div></section></main><Footer /></>;
}

function Wishlist() {
  const { wishlist } = useStore(); const saved = products.filter(p => wishlist.includes(p.id));
  return <><Meta title="Saved pieces" description="Your saved FurniVision pieces, gathered in one place." /><main className="mx-auto max-w-[1440px] px-5 py-12 md:px-8 md:py-20"><p className="font-mono-ui text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]">Your point of view</p><div className="mt-4 flex items-end justify-between gap-4 border-b border-[hsl(var(--border))] pb-9"><h1 className="font-display text-6xl leading-[.9] tracking-[-.05em] md:text-8xl">Saved <em>pieces.</em></h1><p className="font-mono-ui text-[10px] uppercase tracking-[.15em] text-[hsl(var(--muted-foreground))]">{saved.length} saved</p></div>{saved.length ? <div className="mt-10 grid grid-cols-2 gap-x-4 gap-y-12 md:grid-cols-4 md:gap-6">{saved.map((p, i) => <ProductCard key={p.id} product={p} index={i} />)}</div> : <div className="grid min-h-[360px] place-items-center text-center"><div><Heart size={29} className="mx-auto mb-5 text-[hsl(var(--accent))]" /><h2 className="font-display text-4xl">Keep a shortlist.</h2><p className="mt-3 max-w-sm text-sm leading-6 text-[hsl(var(--muted-foreground))]">Tap the heart on any piece that makes you pause. We’ll keep it here.</p><Link href="/shop" className="mt-7 inline-flex items-center gap-2 border-b border-[hsl(var(--foreground))] pb-2 text-sm font-semibold" data-testid="link-empty-wishlist">Explore the collection <ArrowRight size={15} /></Link></div></div>}</main><Footer /></>;
}

function Cart() {
  const { cart, setQuantity, removeCart, cartTotal } = useStore(); const [checkout, setCheckout] = useState(false); const [confirmed, setConfirmed] = useState(false);
  const lines = cart.map(l => ({ ...l, product: getProduct(l.productId)! })).filter(l => l.product);
  if (confirmed) return <main className="mx-auto grid min-h-[calc(100svh-72px)] max-w-xl place-items-center px-5 py-20 text-center"><div className="animate-rise"><div className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-[hsl(var(--accent))] text-white"><Check size={30} /></div><p className="mt-7 font-mono-ui text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]">Order received</p><h1 className="mt-4 font-display text-6xl leading-[.9]">A good<br /><em>choice.</em></h1><p className="mt-6 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Your demo order is confirmed. We’ll send a thoughtful delivery update to your inbox.</p><Link href="/shop" className="mt-8 inline-flex items-center gap-2 bg-[hsl(var(--primary))] px-5 py-3 text-sm font-semibold text-[hsl(var(--primary-foreground))]" data-testid="link-confirmed-shop">Continue shopping <ArrowRight size={15} /></Link></div></main>;
  return <><Meta title={checkout ? 'Checkout' : 'Your cart'} description={checkout ? 'Complete your FurniVision order.' : 'Review your selected FurniVision pieces.'} /><main className="mx-auto max-w-[1440px] px-5 py-10 md:px-8 md:py-16">{checkout ? <CheckoutForm onDone={() => setConfirmed(true)} /> : <><div className="flex items-end justify-between border-b border-[hsl(var(--border))] pb-9"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]">Ready when you are</p><h1 className="mt-4 font-display text-6xl leading-[.9] tracking-[-.05em] md:text-8xl">Your <em>cart.</em></h1></div><p className="font-mono-ui text-[10px] uppercase tracking-[.15em] text-[hsl(var(--muted-foreground))]">{cart.length} {cart.length === 1 ? 'piece' : 'pieces'}</p></div>{lines.length ? <div className="mt-10 grid gap-12 lg:grid-cols-[1fr_360px]"><div className="divide-y divide-[hsl(var(--border))]">{lines.map(({ product, quantity }) => <div className="flex gap-4 py-5 first:pt-0 md:gap-6" key={product.id} data-testid={`row-cart-${product.id}`}><Link href={`/product/${product.slug}`} className="h-28 w-28 shrink-0 overflow-hidden bg-[hsl(var(--secondary))] md:h-40 md:w-40"><img src={product.image} alt={product.name} className="h-full w-full object-cover" /></Link><div className="flex min-w-0 flex-1 flex-col justify-between"><div className="flex justify-between gap-3"><div><p className="font-semibold">{product.name}</p><p className="mt-1 font-mono-ui text-[10px] uppercase tracking-[.12em] text-[hsl(var(--muted-foreground))]">{product.material}</p></div><p className="text-sm">{money(product.price * quantity)}</p></div><div className="flex items-end justify-between"><div className="flex items-center border border-[hsl(var(--border))]"><button onClick={() => setQuantity(product.id, quantity - 1)} aria-label={`Decrease ${product.name} quantity`} className="grid h-8 w-8 place-items-center" data-testid={`button-decrease-${product.id}`}><Minus size={13} /></button><span className="w-7 text-center font-mono-ui text-xs" data-testid={`text-quantity-${product.id}`}>{quantity}</span><button onClick={() => setQuantity(product.id, quantity + 1)} aria-label={`Increase ${product.name} quantity`} className="grid h-8 w-8 place-items-center" data-testid={`button-increase-${product.id}`}><Plus size={13} /></button></div><button onClick={() => removeCart(product.id)} aria-label={`Remove ${product.name}`} className="text-[hsl(var(--muted-foreground))] transition hover:text-[hsl(var(--accent))]" data-testid={`button-remove-${product.id}`}><Trash2 size={16} /></button></div></div></div>)}</div><aside className="h-fit bg-[hsl(var(--secondary))] p-6 md:p-7"><p className="font-mono-ui text-[10px] uppercase tracking-[.18em]">Order summary</p><div className="mt-6 space-y-4 text-sm"><div className="flex justify-between"><span>Subtotal</span><span>{money(cartTotal)}</span></div><div className="flex justify-between"><span>Delivery</span><span>Included</span></div><div className="flex justify-between border-t border-[hsl(var(--border))] pt-4 text-base font-semibold"><span>Total</span><span>{money(cartTotal)}</span></div></div><button onClick={() => setCheckout(true)} className="mt-7 flex w-full items-center justify-center gap-3 bg-[hsl(var(--primary))] px-5 py-4 text-sm font-semibold text-[hsl(var(--primary-foreground))] transition hover:bg-[hsl(var(--accent))]" data-testid="button-checkout">Checkout <ArrowRight size={16} /></button><p className="mt-4 text-center text-xs leading-5 text-[hsl(var(--muted-foreground))]">White glove delivery included on every order.</p></aside></div> : <div className="grid min-h-[400px] place-items-center text-center"><div><ShoppingBag size={29} className="mx-auto mb-5 text-[hsl(var(--accent))]" /><h2 className="font-display text-4xl">A little room to fill.</h2><p className="mt-3 text-sm text-[hsl(var(--muted-foreground))]">Your cart is waiting for its first good piece.</p><Link href="/shop" className="mt-7 inline-flex items-center gap-2 border-b border-[hsl(var(--foreground))] pb-2 text-sm font-semibold" data-testid="link-empty-cart">Shop the collection <ArrowRight size={15} /></Link></div></div>}</>}</main></>;
}

function CheckoutForm({ onDone }: { onDone: () => void }) {
  const [busy, setBusy] = useState(false);
  const submit = (e: FormEvent) => { e.preventDefault(); setBusy(true); window.setTimeout(onDone, 900); };
  return <div className="grid gap-12 lg:grid-cols-[1fr_380px]"><div><button onClick={() => window.history.back()} className="mb-8 inline-flex items-center gap-2 text-xs font-semibold" data-testid="button-back-cart"><ArrowLeft size={15} /> Back to cart</button><p className="font-mono-ui text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]">Almost home</p><h1 className="mt-4 font-display text-6xl leading-[.9] tracking-[-.05em] md:text-8xl">Checkout.</h1><form onSubmit={submit} className="mt-12 grid gap-8"><fieldset className="grid gap-5"><legend className="mb-1 font-display text-2xl">Contact</legend><label className="grid gap-2 text-xs font-semibold">Email<input required type="email" placeholder="you@example.com" className="border-b border-[hsl(var(--foreground)/.3)] bg-transparent px-0 py-3 text-sm outline-none focus:border-[hsl(var(--accent))]" data-testid="input-checkout-email" /></label></fieldset><fieldset className="grid gap-5"><legend className="mb-1 font-display text-2xl">Delivery address</legend><div className="grid gap-5 md:grid-cols-2"><label className="grid gap-2 text-xs font-semibold md:col-span-2">Full name<input required placeholder="Your name" className="border-b border-[hsl(var(--foreground)/.3)] bg-transparent px-0 py-3 text-sm outline-none focus:border-[hsl(var(--accent))]" data-testid="input-checkout-name" /></label><label className="grid gap-2 text-xs font-semibold md:col-span-2">Address<input required placeholder="Street and number" className="border-b border-[hsl(var(--foreground)/.3)] bg-transparent px-0 py-3 text-sm outline-none focus:border-[hsl(var(--accent))]" data-testid="input-checkout-address" /></label><label className="grid gap-2 text-xs font-semibold">City<input required placeholder="City" className="border-b border-[hsl(var(--foreground)/.3)] bg-transparent px-0 py-3 text-sm outline-none focus:border-[hsl(var(--accent))]" data-testid="input-checkout-city" /></label><label className="grid gap-2 text-xs font-semibold">Postal code<input required placeholder="Postal code" className="border-b border-[hsl(var(--foreground)/.3)] bg-transparent px-0 py-3 text-sm outline-none focus:border-[hsl(var(--accent))]" data-testid="input-checkout-postal" /></label></div></fieldset><fieldset className="grid gap-5"><legend className="mb-1 font-display text-2xl">Payment</legend><label className="grid gap-2 text-xs font-semibold">Card number<input required inputMode="numeric" placeholder="4242 4242 4242 4242" className="border-b border-[hsl(var(--foreground)/.3)] bg-transparent px-0 py-3 text-sm outline-none focus:border-[hsl(var(--accent))]" data-testid="input-checkout-card" /></label><div className="grid gap-5 md:grid-cols-2"><label className="grid gap-2 text-xs font-semibold">Expiry<input required placeholder="MM / YY" className="border-b border-[hsl(var(--foreground)/.3)] bg-transparent px-0 py-3 text-sm outline-none" data-testid="input-checkout-expiry" /></label><label className="grid gap-2 text-xs font-semibold">CVC<input required placeholder="123" className="border-b border-[hsl(var(--foreground)/.3)] bg-transparent px-0 py-3 text-sm outline-none" data-testid="input-checkout-cvc" /></label></div></fieldset><button disabled={busy} className="mt-2 flex items-center justify-center gap-3 bg-[hsl(var(--primary))] px-5 py-4 text-sm font-semibold text-[hsl(var(--primary-foreground))] disabled:opacity-60" data-testid="button-place-order">{busy ? 'Confirming your order…' : <>Place demo order <ArrowRight size={16} /></>}</button></form></div><div className="hidden bg-[hsl(var(--secondary))] p-7 lg:block"><p className="font-mono-ui text-[10px] uppercase tracking-[.18em]">The FurniVision promise</p><div className="mt-8 grid gap-7"><div><Truck className="mb-3 text-[hsl(var(--accent))]" size={21} /><p className="font-semibold">Room-ready delivery</p><p className="mt-1 text-sm leading-5 text-[hsl(var(--muted-foreground))]">We bring it in, place it, and take the packaging with us.</p></div><div><ShieldCheck className="mb-3 text-[hsl(var(--accent))]" size={21} /><p className="font-semibold">Secure checkout</p><p className="mt-1 text-sm leading-5 text-[hsl(var(--muted-foreground))]">This is a demo checkout — no payment is processed.</p></div></div></div></div>;
}

function AccountPage({ user, orders }: { user: User | null; orders: StoreOrder[] }) {
  const [, setLocation] = useLocation();
  const [mode, setMode] = useState<'signin' | 'signup'>('signin');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);

  const finishAuth = async (action: () => Promise<AuthResult>) => {
    setBusy(true);
    setMessage('');
    const result = await action();
    if (result.user) setLocation('/');
    else setMessage(result.error || 'Please try again.');
    setBusy(false);
  };

  if (!user) return <main className="mx-auto grid min-h-[calc(100svh-72px)] max-w-5xl items-center gap-12 px-5 py-16 md:grid-cols-2 md:px-8">
    <div><p className="font-mono-ui text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]">FurniVision / Your account</p><h1 className="mt-5 font-display text-6xl leading-[.9] tracking-[-.05em]">Keep the<br /><em>good stuff.</em></h1><p className="mt-6 max-w-sm text-sm leading-6 text-[hsl(var(--muted-foreground))]">Save pieces, place orders, and keep delivery details in one place. Store owners can also open the admin control room here.</p></div>
    <div className="border border-[hsl(var(--border))] bg-[hsl(var(--secondary))] p-6 md:p-8"><div className="mb-7 flex border-b border-[hsl(var(--border))]"><button onClick={() => setMode('signin')} className={`flex-1 pb-3 text-sm font-semibold ${mode === 'signin' ? 'border-b-2 border-[hsl(var(--accent))]' : 'text-[hsl(var(--muted-foreground))]'}`}>Sign in</button><button onClick={() => setMode('signup')} className={`flex-1 pb-3 text-sm font-semibold ${mode === 'signup' ? 'border-b-2 border-[hsl(var(--accent))]' : 'text-[hsl(var(--muted-foreground))]'}`}>Sign up</button></div><form onSubmit={(event) => { event.preventDefault(); void finishAuth(() => mode === 'signin' ? signIn(email, password) : createAccount(email, password)); }} className="grid gap-5"><label className="grid gap-2 text-xs font-semibold">Email<input required type="email" value={email} onChange={(event) => setEmail(event.target.value)} autoComplete="email" /></label><label className="grid gap-2 text-xs font-semibold">Password<input required minLength={6} type="password" value={password} onChange={(event) => setPassword(event.target.value)} autoComplete={mode === 'signin' ? 'current-password' : 'new-password'} /></label>{message && <p className="text-sm text-[hsl(var(--destructive))]" role="alert">{message}</p>}<button disabled={busy} className="flex items-center justify-center gap-2 bg-[hsl(var(--primary))] px-5 py-3 text-sm font-semibold text-[hsl(var(--primary-foreground))] disabled:opacity-60"><LockKeyhole size={15} /> {busy ? 'Working…' : mode === 'signin' ? 'Sign in' : 'Create account'}</button></form><div className="my-5 flex items-center gap-3 text-[10px] uppercase tracking-[.15em] text-[hsl(var(--muted-foreground))]"><span className="h-px flex-1 bg-[hsl(var(--border))]" />or<span className="h-px flex-1 bg-[hsl(var(--border))]" /></div><button disabled={busy} onClick={() => void finishAuth(signInWithGoogle)} className="w-full border border-[hsl(var(--foreground)/.25)] px-5 py-3 text-sm font-semibold disabled:opacity-60">Continue with Google</button><p className="mt-5 text-center text-xs leading-5 text-[hsl(var(--muted-foreground))]">The first account claimed from the Admin room becomes the protected storefront owner.</p></div>
  </main>;

  return <main className="mx-auto max-w-5xl px-5 py-12 md:px-8 md:py-20"><div className="flex flex-wrap items-end justify-between gap-5 border-b border-[hsl(var(--border))] pb-8"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]">FurniVision / Account</p><h1 className="mt-4 font-display text-6xl leading-[.9]">Good to<br /><em>see you.</em></h1><p className="mt-5 text-sm text-[hsl(var(--muted-foreground))]">{user.email}</p></div><div className="flex gap-3"><Link href="/admin" className="inline-flex items-center gap-2 bg-[hsl(var(--primary))] px-4 py-3 text-sm font-semibold text-[hsl(var(--primary-foreground))]">Admin room <ShieldCheck size={15} /></Link><button onClick={() => void signOutUser()} className="border border-[hsl(var(--border))] px-4 py-3 text-sm font-semibold">Sign out</button></div></div><section className="mt-10"><div className="flex items-end justify-between"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]">Your pieces</p><h2 className="mt-2 font-display text-4xl">Order history</h2></div><span className="font-mono-ui text-xs text-[hsl(var(--muted-foreground))]">{orders.length} orders</span></div>{orders.length ? <div className="mt-6 divide-y divide-[hsl(var(--border))] border-y border-[hsl(var(--border))]">{orders.map((order) => <article className="flex flex-wrap items-center justify-between gap-4 py-5" key={order.id}><div><p className="font-mono-ui text-[10px] uppercase tracking-[.14em] text-[hsl(var(--muted-foreground))]">{order.id} · {new Date(order.createdAt).toLocaleDateString()}</p><h3 className="mt-2 text-sm font-semibold">{order.items.map((item) => item.name).join(', ')}</h3><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{order.status} · {order.customer.city}</p></div><strong>{money(order.total)}</strong></article>)}</div> : <div className="mt-6 border border-dashed border-[hsl(var(--border))] p-10 text-center"><p className="font-display text-3xl">Your first room is still ahead.</p><Link href="/shop" className="mt-5 inline-flex border-b border-[hsl(var(--foreground))] pb-1 text-sm font-semibold">Shop the collection</Link></div>}</section></main>;
}

function NotFound() { return <main className="grid min-h-[calc(100svh-72px)] place-items-center px-5 text-center"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.2em] text-[hsl(var(--accent))]">404 / wrong room</p><h1 className="mt-5 font-display text-7xl">Not here.</h1><p className="mt-4 text-sm text-[hsl(var(--muted-foreground))]">The piece you’re looking for may have moved.</p><Link href="/shop" className="mt-7 inline-flex items-center gap-2 border-b border-[hsl(var(--foreground))] pb-2 text-sm font-semibold" data-testid="link-notfound-shop">Back to shop <ArrowRight size={15} /></Link></div></main>; }

function App() {
  const [wishlist, setWishlist] = useStored<string[]>('furnivision-wishlist', []);
  const [cart, setCart] = useStored<CartLine[]>('furnivision-cart', []);
  const [user, setUser] = useState<User | null>(null);
  const [orders, setOrders] = useState<StoreOrder[]>([]);
  const [, setCatalogVersion] = useState(0);
  const addCart = (id: string) => setCart(current => current.some(l => l.productId === id) ? current.map(l => l.productId === id ? { ...l, quantity: l.quantity + 1 } : l) : [...current, { productId: id, quantity: 1 }]);
  const setQuantity = (id: string, quantity: number) => setCart(current => quantity < 1 ? current.filter(l => l.productId !== id) : current.map(l => l.productId === id ? { ...l, quantity } : l));
  const removeCart = (id: string) => setCart(current => current.filter(l => l.productId !== id));
  const toggleWish = (id: string) => setWishlist(current => current.includes(id) ? current.filter(x => x !== id) : [...current, id]);
  const reloadCatalog = async () => {
    try {
      const catalog = await loadCatalog();
      if (catalog && catalog.length > 0) products = catalog.map(catalogToProduct);
      else products = fallbackProducts;
      setCatalogVersion((value) => value + 1);
    } catch {
      products = fallbackProducts;
    }
  };
  useEffect(() => { void reloadCatalog(); return subscribeToAuth((current) => { setUser(current); if (current) void loadCustomerOrders(current.uid).then(setOrders); else setOrders([]); }); }, []);
  const store = { wishlist, cart, toggleWish, addCart, setQuantity, removeCart, cartCount: cart.reduce((sum, l) => sum + l.quantity, 0), cartTotal: cart.reduce((sum, l) => sum + (getProduct(l.productId)?.price || 0) * l.quantity, 0) };
  return <StoreContext.Provider value={store}><div className="texture min-h-[100dvh]"><Header /><Switch><Route path="/" component={Home} /><Route path="/shop" component={Shop} /><Route path="/product/:slug" component={ProductDetail} /><Route path="/wishlist" component={Wishlist} /><Route path="/cart" component={Cart} /><Route path="/account" component={() => <AccountPage user={user} orders={orders} />} /><Route path="/admin" component={() => <AdminDashboard user={user} onCatalogChange={reloadCatalog} />} /><Route component={NotFound} /></Switch></div></StoreContext.Provider>;
}

export default App;